ArC0haJ;;AqC3haE;EACE,aAAA;ArC8haJ;;AqC/haE;EACE,aAAA;ArCkiaJ;;AqCniaE;EACE,aAAA;ArCsiaJ;;AqCviaE;EACE,aAAA;ArC0iaJ;;AqC3iaE;EACE,aAAA;ArC8iaJ;;AsC7kaA;;;;EAAA;AASA;EACE,0CAAA;EACA,0DAAA;EAEA,8EAAA;EACA,mDAAA;AtC2kaF;;AsCvkaE;EACE,kCAAA;EACA,kBAAA;EACA,gBAAA;EACA,mBH6BqB;EG5BrB,oEAAA;AtC0kaJ;AsCtkaA;EACE,qCAAA;EACA,eAAA;AtCwkaF;;AsCrkaA;EACE,qCAAA;AtCwkaF;;AsCrkaA;EACE,eAAA;AtCwkaF","file":"style.css","sourcesContent":["@charset \"UTF-8\";\n/*!------------------------------------------------------------------\n[MAIN STYLESHEET]\n\nPROJECT:\tThomson\nVERSION:\t1.0\n-------------------------------------------------------------------*/\n/*------------------------------------------------------------------\n[TABLE OF CONTENTS]\n-------------------------------------------------------------------*/\n@import url(\"https://fonts.googleapis.com/css?family=Lato:400,600,700|Work+Sans:400,700,800\");\nhtml {\n  overflow-x: hidden;\n}\n\nbody {\n  font-family: \"Lato\", sans-serif;\n  -webkit-font-smoothing: antialiased;\n  font-size: 16px;\n  font-weight: 400;\n  letter-spacing: 0.166667px;\n  line-height: 1.7em;\n  color: #818385;\n}\n\np {\n  color: #818385;\n}\n\nh1, .h1, h2, .h2, h3, .h3, h4, .h4, h5, .h5, h6, .h6 {\n  font-family: \"Work Sans\", sans-serif;\n  color: #000;\n  font-weight: 600;\n}\n\nh1, .h1 {\n  font-size: 45px;\n  text-transform: none;\n}\n\nh2, .h2 {\n  font-size: 42px;\n  line-height: 52px;\n}\n\nh3, .h3 {\n  font-size: 24px;\n  line-height: 34px;\n}\n\nh4, .h4 {\n  font-size: 20px;\n  line-height: 30px;\n}\n\nh5, .h5 {\n  font-size: 16px;\n  line-height: 26px;\n}\n\nh6, .h6 {\n  font-size: 14px;\n}\n\n.text-sm {\n  font-size: 14px;\n}\n\n.section {\n  padding: 120px 0px;\n}\n\n.section-sm {\n  padding: 60px 0px;\n}\n\n.btn {\n  padding: 18px 38px;\n  border: 2px solid transparent;\n  text-transform: uppercase;\n  border-radius: 0px;\n  font-size: 14px;\n  line-height: 14px;\n  font-weight: 600;\n  box-shadow: rgb(153, 153, 153) 0px 0px 0px 0px;\n}\n.btn:focus {\n  outline: 0px;\n  border: 0px;\n  box-shadow: none;\n}\n\n.btn-main {\n  background: #f44336;\n  color: #fff;\n}\n.btn-main:hover {\n  color: #fff !important;\n  background: #000;\n}\n\n.btn-black {\n  background: #000;\n  color: #fff;\n}\n.btn-black:hover {\n  background: #f44336;\n  color: #fff;\n}\n\n.btn-white {\n  background: #fff;\n  color: #000;\n  border-color: #fff;\n}\n.btn-white:hover {\n  background: transparent;\n  color: #fff;\n}\n\na {\n  color: #000;\n  -webkit-transition: all 0.25s ease;\n  -moz-transition: all 0.25s ease;\n  -ms-transition: all 0.25s ease;\n  -o-transition: all 0.25s ease;\n  transition: all 0.25s ease;\n}\na:hover {\n  color: #f44336;\n  text-decoration: none;\n  outline: none;\n}\n\n.bg-primary {\n  background: #f44336 !important;\n}\n\n.bg-secondary {\n  background: #f7f7f7 !important;\n}\n\n.bg-extra {\n  background: #e8eefb !important;\n}\n\n.text-color {\n  color: #f44336;\n}\n\n.page-title h1 {\n  position: relative;\n  padding-bottom: 30px;\n}\n.page-title h1:after {\n  position: absolute;\n  content: \"\";\n  left: 50%;\n  bottom: 0px;\n  width: 40px;\n  height: 2px;\n  margin-left: -25px;\n  background: #f44336;\n}\n\n@media (max-width: 575px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n@media (max-width: 400px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n/* ===================================\n   Language Switcher\n   =================================== */\n.language-switcher-container {\n  align-content: center;\n}\n\n.language-switcher .lang-toggle {\n  display: inline-flex;\n  position: relative;\n  background: rgba(255, 255, 255, 0.1);\n  border: 1px solid rgba(255, 255, 255, 0.2);\n  border-radius: 50px;\n  padding: 3px; /* reduced from 4px */\n  overflow: hidden;\n  align-items: center; /* vertically center buttons */\n  box-sizing: border-box;\n}\n.language-switcher .lang-btn {\n  position: relative;\n  z-index: 2;\n  background: transparent;\n  border: none;\n  color: rgba(132, 132, 132, 0.7);\n  font-size: 10px; /* reduced from 12px */\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.3px; /* reduced from 0.5px */\n  padding: 4px 12px; /* reduced from 6px 16px */\n  border-radius: 36px; /* slightly smaller */\n  cursor: pointer;\n  transition: color 0.3s ease;\n  white-space: nowrap;\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.language-switcher .lang-btn:hover {\n  color: #000; /* darker on hover */\n}\n.language-switcher .lang-btn.active {\n  color: #fff !important; /* white text on red slider - high contrast */\n}\n.language-switcher .lang-btn .lang-text {\n  display: inline-block;\n  transition: transform 0.2s ease, opacity 0.2s ease;\n}\n.language-switcher .lang-slider {\n  position: absolute;\n  top: 3px; /* matches toggle padding */\n  left: 3px; /* matches toggle padding */\n  height: calc(100% - 6px); /* matches toggle padding * 2 */\n  background: #f44336 !important; /* explicit red - $primary-color */\n  border-radius: 36px; /* matches button radius */\n  box-shadow: 0 2px 6px rgba(244, 67, 54, 0.5);\n  transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), width 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);\n  z-index: 1;\n  pointer-events: none;\n  /* Initial fallback width - will be overridden by JS */\n  width: 30px;\n  transform: translateX(0);\n}\n.language-switcher {\n  /* JS will handle positioning via inline styles */\n  /* Fallback for no-JS - positioned based on active button */\n}\n.language-switcher .lang-btn[data-lang=it].active ~ .lang-slider {\n  transform: translateX(0);\n  width: 30px;\n  background: #f44336 !important;\n}\n.language-switcher .lang-btn[data-lang=en].active ~ .lang-slider {\n  transform: translateX(calc(100% + 3px)); /* matches toggle padding */\n  width: 30px;\n  background: #f44336 !important;\n}\n.language-switcher {\n  /* Animation on language change */\n}\n.language-switcher .lang-switching .lang-slider {\n  transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1), width 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);\n}\n.language-switcher .lang-switching .lang-btn {\n  transition: color 0.2s ease;\n}\n.language-switcher {\n  /* Mobile adjustments */\n}\n@media (max-width: 575px) {\n  .language-switcher .lang-toggle {\n    padding: 2px;\n  }\n  .language-switcher .lang-btn {\n    font-size: 9px;\n    padding: 3px 10px;\n  }\n  .language-switcher .lang-slider {\n    top: 2px;\n    height: calc(100% - 4px);\n  }\n}\n.language-switcher {\n  /* Align with navbar nav-links */\n}\n.language-switcher .navbar-nav .nav-item > .language-switcher {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  height: 100%;\n  padding: 0 15px; /* match nav-link horizontal padding */\n  margin: 0;\n}\n.language-switcher .navbar-nav .nav-item > .language-switcher .lang-toggle {\n  height: 100%;\n  display: flex;\n  align-items: center;\n  padding: 0 3px; /* internal padding for slider */\n}\n.language-switcher {\n  /* Ensure nav-item with language switcher aligns properly */\n}\n.language-switcher .navbar-nav .nav-item.nav-item-lang {\n  display: flex;\n  align-items: center;\n}\n.language-switcher {\n  /* Standalone class for li containing language switcher */\n}\n.language-switcher .nav-item-lang {\n  display: flex;\n  align-items: center;\n}\n.language-switcher {\n  /* Utility: force flex center alignment */\n}\n.language-switcher .flex-center {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n/* Page transition animation on language change */\n.lang-page-transition {\n  opacity: 0;\n  transform: translateY(10px);\n  transition: opacity 0.3s ease, transform 0.3s ease;\n}\n\n.lang-page-transition.loaded {\n  opacity: 1;\n  transform: translateY(0);\n}\n\ntable td img,\ntable th img {\n  display: block !important;\n  margin-left: auto !important;\n  margin-right: auto !important;\n  width: auto !important;\n  height: auto 