--------------------------------------------------\n[TABLE OF CONTENTS]\n-------------------------------------------------------------------*/\n\n@import 'variables.scss';\n\n@import 'typography.scss';\n\n@import 'mixins.scss';\n\n@import 'buttons.scss';\n\n@import 'common.scss';\n@import 'templates/slider.scss';\n@import 'templates/navigation.scss';\n@import 'templates/portfolio.scss';\n@import 'templates/service.scss';\n@import 'templates/testimonial.scss';\n@import 'templates/about.scss';\n@import 'templates/contact.scss';\n@import 'templates/blog.scss';\n@import 'templates/footer.scss';\n\n@import 'powpow/item-portfolio.scss';\n@import 'powpow/rainbow-border.scss';\n@import 'powpow/general-purpose.scss';\n@import 'powpow/rainbow-float-effect.scss';\n@import 'powpow/jump-effect.scss';\n@import 'powpow/portfolio-single.scss';\n\n@import 'table-of-contents.scss';\n\n@import 'callouts.scss';\n@import 'headings.scss';\n@import 'code-foldable.scss';\n\n@import '../images/Assets/fontAwesome/scss/fontawesome.scss';\n@import '../images/Assets/fontAwesome/scss/brands.scss';\n@import '../images/Assets/fontAwesome/scss/solid.scss';","@import url('https://fonts.googleapis.com/css?family=Lato:400,600,700|Work+Sans:400,700,800');\n\n\nhtml{\n  overflow-x: hidden;\n}\n\nbody {\n  font-family: $body-font;\n  -webkit-font-smoothing: antialiased;\n  font-size: 16px;\n  font-weight: 400;\n  letter-spacing: 0.166667px;\n  line-height:1.7em;\n  color: #818385;\n\n}\n\np{\n  color:#818385;\n}\nh1,.h1,h2,.h2,h3,.h3,h4,.h4,h5,.h5,h6,.h6 {\n  font-family: $heading-font;\n  color: $black;\n  font-weight: 600;\n}\n\nh1 ,.h1{\n  font-size: 45px;\n  text-transform: none;\n}\n\nh2,.h2 {\n  font-size: 42px;\n  line-height: 52px;\n}\n\nh3,.h3 {\n  font-size: 24px;\n  line-height: 34px;\n}\n\nh4,.h4 {\n  font-size: 20px;\n  line-height: 30px;\n}\n\nh5,.h5 {\n  font-size: 16px;\n  line-height: 26px;\n}\n\nh6,.h6 {\n  font-size: 14px;\n}\n\n\n.text-sm{\n  font-size: 14px;\n}","// Color Variables\n$white: #fff;\n$black: #000;\n$border-color: #dedede;\n$heading-font:'Work Sans', sans-serif;\n$body-font:'Lato', sans-serif;\n$extra-color:#e8eefb;\n$primary-color:#f44336;\n$secondary-color:#f7f7f7;",".section{\n\tpadding: 120px 0px;\n}\n\n.section-sm{\n\tpadding: 60px 0px;\n}\n\n.btn{\n\tpadding: 18px 38px;\n\tborder: 2px solid transparent;\n\ttext-transform: uppercase;\n\tborder-radius:0px;\n\tfont-size: 14px;\n\tline-height: 14px;\n\tfont-weight: 600;\n\tbox-shadow: rgb(153, 153, 153) 0px 0px 0px 0px;\n\n\t &:focus{\n\t    outline: 0px;\n\t    border: 0px;\n\t    box-shadow: none;\n\t  }\n}\n\n.btn-main{\n\tbackground: $primary-color;\n\tcolor: $white;\n\n\t&:hover{\n\t\tcolor: $white!important;\n\t\tbackground: $black;\n\t}\n}\n\n.btn-black{\n\tbackground: $black;\n\tcolor: $white;\n\n\t&:hover{\n\t\tbackground: $primary-color;\n\t\tcolor: $white;\n\t}\n}\n\n.btn-white{\n\tbackground: $white;\n\tcolor: $black;\n\tborder-color: $white;\n\n\t&:hover{\n\t\tbackground: transparent;\n\t\tcolor: $white;\n\t}\n}\n\n\na{\n\tcolor: $black;\n\t-webkit-transition: all .25s ease;\n\t   -moz-transition: all .25s ease;\n\t    -ms-transition: all .25s ease;\n\t     -o-transition: all .25s ease;\n\t        transition: all .25s ease;\n\n\t&:hover{\n\t\tcolor: $primary-color;\n\t\ttext-decoration: none;\n\t\toutline:none;\n\t}\n\n}\n\n\n\n.bg-primary{\n\tbackground: $primary-color!important;\n}\n\n.bg-secondary{\n\tbackground: $secondary-color!important;\n}\n.bg-extra{\n\tbackground: $extra-color!important;\n}\n\n.text-color{\n\tcolor: $primary-color;\n}\n\n.page-title{\n\th1{\n\t\tposition: relative;\n\t\tpadding-bottom: 30px;\n\n\t\t&:after{\n\t\t\tposition: absolute;\n\t\t\tcontent:\"\";\n\t\t\tleft: 50%;\n\t\t\tbottom:0px;\n\t\t\twidth: 40px;\n\t\t\theight: 2px;\n\t\t\tmargin-left: -25px;\n\t\t\tbackground: $primary-color;\n\t\t}\n\t}\n}\n\n\n@include mobile{\n\th2, .h2 {\n\t    font-size: 32px;\n\t    line-height: 43px;\n\t}\n}\n\n@include mobile-xs{\n\th2, .h2 {\n\t    font-size: 32px;\n\t    line-height: 43px;\n\t}\n}\n\n/* ===================================\n   Language Switcher\n   =================================== */\n\n.language-switcher-container\n{\n  align-content: center;\n}\n\n.language-switcher {\n.lang-toggle {\n    display: inline-flex;\n    position: relative;\n    background: rgba(255, 255, 255, 0.1);\n    border: 1px solid rgba(255, 255, 255, 0.2);\n    border-radius: 50px;\n    padding: 3px;  /* reduced from 4px */\n    overflow: hidden;\n    align-items: center;  /* vertically center buttons */\n    box-sizing: border-box;\n  }\n\n  .lang-btn {\n    position: relative;\n    z-index: 2;\n    background: transparent;\n    border: none;\n    color: rgb(132 132 132 / 70%);\n    font-size: 10px;  /* reduced from 12px */\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.3px;  /* reduced from 0.5px */\n    padding: 4px 12px;  /* reduced from 6px 16px */\n    border-radius: 36px;  /* slightly smaller */\n    cursor: pointer;\n    transition: color 0.3s ease;\n    white-space: nowrap;\n    box-sizing: border-box;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n\n    &:hover {\n      color: #000;  /* darker on hover */\n    }\n\n    &.active {\n      color: #fff !important;  /* white text on red slider - high contrast */\n    }\n\n    .lang-text {\n      display: inline-block;\n      transition: transform 0.2s ease, opacity 0.2s ease;\n    }\n  }\n\n  .lang-slider {\n    position: absolute;\n    top: 3px;  /* matches toggle padding */\n    left: 3px;  /* matches toggle padding */\n    height: calc(100% - 6px);  /* matches toggle padding * 2 */\n    background: #f44336 !important;  /* explicit red - $primary-color */\n    border-radius: 36px;  /* matches button radius */\n    box-shadow: 0 2px 6px rgba(244, 67, 54, 0.5);\n    transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), width 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);\n    z-index: 1;\n    pointer-events: none;\n    /* Initial fallback width - will be overridden by JS */\n    width: 30px;\n    transform: translateX(0);\n  }\n\n  /* JS will handle positioning via inline styles */\n  /* Fallback for no-JS - positioned based on active button */\n  .lang-btn[data-lang=\"it\"].active ~ .lang-slider {\n    transform: translateX(0);\n    width: 30px;\n    background: #f44336 !important;\n  }\n\n  .lang-btn[data-lang=\"en\"].active ~ .lang-slider {\n    transform: translateX(calc(100% + 3px));  /* matches toggle padding */\n    width: 30px;\n    background: #f44336 !important;\n  }\n\n  /* Animation on language change */\n  .lang-switching .lang-slider {\n    transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1), width 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);\n  }\n\n  .lang-switching .lang-btn {\n    transition: color 0.2s ease;\n  }\n\n  /* Mobile adjustments */\n  @include mobile {\n    .lang-toggle {\n      padding: 2px;\n    }\n\n    .lang-btn {\n      font-size: 9px;\n      padding: 3px 10px;\n    }\n\n    .lang-slider {\n      top: 2px;\n      height: calc(100% - 4px);\n    }\n  }\n\n  /* Align with navbar nav-links */\n  .navbar-nav .nav-item > .language-switcher {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    height: 100%;\n    padding: 0 15px;  /* match nav-link horizontal padding */\n    margin: 0;\n  }\n\n  .navbar-nav .nav-item > .language-switcher .lang-toggle {\n    height: 100%;\n    display: flex;\n    align-items: center;\n    padding: 0 3px;  /* internal padding for slider */\n  }\n\n  /* Ensure nav-item with language switcher aligns properly */\n  .navbar-nav .nav-item.nav-item-lang {\n    display: flex;\n    align-items: center;\n  }\n\n  /* Standalone class for li containing language switcher */\n  .nav-item-lang {\n    display: flex;\n    align-items: center;\n  }\n\n  /* Utility: force flex center alignment */\n  .flex-center {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n}\n\n/* Page transition animation on language change */\n.lang-page-transition {\n  opacity: 0;\n  transform: translateY(10px);\n  transition: opacity 0.3s ease, transform 0.3s ease;\n}\n\n.lang-page-transition.loaded {\n    opacity: 1;\n    transform: translateY(0);\n}\n\ntable td img,\ntable th img {\n    display: block !important;\n    margin-left: auto !important;\n    margin-right: auto !important;\n    width: auto !important;\n    height: auto !important;\n}\n\ntable td,\ntable th {\n    text-align: center !important;\n    align-content: center !important;\n}","@mixin mobile-xs{\n  @media(max-width:400px){\n    @content;\n  }\n}\n@mixin mobile{\n  @media(max-width:575px){\n    @content;\n  }\n}\n@mixin tablet{\n  @media(max-width:767px){\n    @content;\n  }\n}\n@mixin desktop{\n  @media(max-width:991px){\n    @content;\n  }\n}\n@mixin desktop-lg{\n  @media(max-width:1200px){\n    @content;\n  }\n}\n\n@mixin size($size){\n  width: $size; height: $size;\n}",".cd-headline.clip span{\n\tpadding: 0px;\n}\n\n.banner .cd-headline {\n    font-size: 56px;\n    line-height: 70px;\n}\n\n.banner-3{\n\tposition: relative;\n}\n\n",".main-nav {\n\t.header-top-socials{\n\t\ta{\n\t\t\ttext-transform: uppercase;\n\t\t\tletter-spacing: 1px;\n\t\t\tfont-size: 14px;\n\t\t\tpadding: 20px 6px;\n\t\t}\n\t}\n}\n\n.navbar-nav .nav-link {\n\tpadding: 20px 15px!important;\n\ttext-transform: uppercase;\n\tfont-size: 14px;\n\tletter-spacing: 1px;\n    font-weight: 700;\n    text-decoration: none;\n}\n\nul.dropdown-menu {\n    background: rgba(21,21,21,1);\n    border-radius: 0px;\n    margin: 0px;\n    padding: 0px;\n}\nul.dropdown-menu > li > a, .navbar ul ul ul.dropdown-menu li .nav-link {\n    font-size: 12px;\n    line-height: 22px;\n    display: block;\n    position: relative;\n    z-index: 1;\n    padding-left: 15px;\n    -webkit-transition: all .3s ease-in-out;\n    transition: all .3s ease-in-out;\n    padding-top: 10px;\n    padding-bottom: 10px;\n    border-bottom: 1px solid #27243e;\n    color: $white;\n    text-transform: uppercase;\n\n    &:hover{\n        color: $primary-color;\n    }\n}\n\n.dropdown-item:focus, .dropdown-item:hover {\n    color:$white;\n    text-decoration: none;\n    background-color: transparent;\n\n}\n\n.dropdown-menu {\n    border-radius: 0;\n    -moz-border-radius: 0;\n    -webkit-border-radius: 0;\n    -o-border-radius: 0;\n    -ms-border-radius: 0;\n    padding: 0;\n    border: 0;\n    display: block;\n    opacity: 0;\n    visibility: hidden;\n    min-width: 210px;\n    transform: scaleY(0);\n    -webkit-transform: scaleY(0);\n    -moz-transform: scaleY(0);\n    -ms-transform: scaleY(0);\n    -o-transform: scaleY(0);\n    transform-origin: center top 0;\n    -webkit-transform-origin: center top 0;\n    -moz-transform-origin: center top 0;\n    -ms-transform-origin: center top 0;\n    -o-transform-origin: center top 0;\n    transition: all .3s ease-in-out 0s;\n    -webkit-transition: all .3s ease-in-out 0s;\n    -moz-transition: all .3s ease-in-out 0s;\n    -ms-transition: all .3s ease-in-out 0s;\n    -o-transition: all .3s ease-in-out 0s;\n    box-shadow: 0 6px 12px rgba(0,0,0,.175);\n    -webkit-box-shadow: 0 6px 12px rgba(0,0,0,.175);\n    -moz-box-shadow: 0 6px 12px rgba(0,0,0,.175);\n    -ms-box-shadow: 0 6px 12px rgba(0,0,0,.175);\n    -o-box-shadow: 0 6px 12px rgba(0,0,0,.175);\n\n}\n\n.dropdown:hover .dropdown-menu{\n\topacity: 1;\n\tvisibility:visible;\n\t-webkit-transform: scaleY(1);\n    -moz-transform: scaleY(1);\n    -ms-transform: scaleY(1);\n    -o-transform: scaleY(1);\n}\n\n\n@include mobile{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n    .btn-group, .btn-group-vertical {\n        display: block;\n    }\n\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}\n\n\n\n@include mobile-xs{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n     .btn-group, .btn-group-vertical {\n        display: block;\n    }\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}\n\n@include tablet{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n     .btn-group, .btn-group-vertical {\n        display: block;\n    }\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}\n@include desktop{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n     .btn-group, .btn-group-vertical {\n        display: block;\n    }\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}","\n\n// Portfolio\n// \n.portfolio{\n  padding-bottom: 100px;\n\n  .btn:focus,.btn:hover,.btn.focus.active{\n    box-shadow: none!important;\n\t  outline: 0!important;\n  }\n \n  .btn-group .btn{\n    border-radius: 0px!important;\n    padding-left: 0px;\n    font-weight: 700;\n\n    &:hover{\n    \tcolor: $primary-color;\n    }\n  }\n\n  .btn-group:not(:first-child) > .btn, .btn-group > .btn:not(:first-child) {\n    border-top-left-radius: 0px;\n    border-bottom-left-radius: 0px;\n  }\n\n  .btn.active{\n    color: $primary-color;\n  }\n  \n}\n\n .inner-box{\n  position:relative;\n}\n\n.inner-box .image{\n  position:relative;\n  overflow: hidden;\n}\n\n.inner-box .image img{\n  position:relative;\n  width:100%;\n  display:block;\n   -ms-transition: all 0.3s;\n    -moz-transition: all 0.3s;\n    -webkit-transition: all 0.3s;\n    -o-transition: all 0.3s;\n    transition: all 0.3s;\n}\n\n.inner-box .image .overlay-box{\n    position: absolute;\n    left: 0px;\n    bottom: 0px;\n    right: 0px;\n    top: 0px;\n    z-index: 2;\n    opacity: 0;\n    display: block;\n    text-decoration: none;\n    cursor: pointer;\n    -webkit-transition: all .6s ease;\n    -ms-transition: all .6s ease;\n    -o-transition: all .6s ease;\n    transition: all .6s ease;\n    overflow: hidden;\n\n}\n\n.inner-box .image .overlay-box:before{\n  position:absolute;\n  content:'';\n  left:-450px;\n  top:0px;\n  width:100%;\n  height:100%;\n   display:block;\n    opacity:0; \n    -ms-transition: all 0.4s;\n    -moz-transition: all 0.4s;\n    -webkit-transition: all 0.4s;\n    -o-transition: all 0.4s;\n    transition: all 0.4s;\n    background-color:rgba(47, 50, 56 ,.8);\n}\n.inner-box:hover .image img{\n -webkit-transform: scale(1.1);\n    -moz-transform: scale(1.1);\n     -ms-transform: scale(1.1);\n      -o-transform: scale(1.1);\n         transform: scale(1.1);\n}\n.inner-box:hover .image .overlay-box:before{\n  opacity: 1;\n  left: 0px;\n}\n\n\n .inner-box:hover .image .overlay-box{\n  opacity: 1;\n}\n\n .inner-box:hover .image .overlay-box .overlay-content h5{\n      -webkit-transform: translateX(0px);\n         -moz-transform: translateX(0px);\n          -ms-transform: translateX(0px);\n           -o-transform: translateX(0px);\n              transform: translateX(0px);\n}\n .inner-box:hover .image .overlay-box .overlay-content p{\n      -webkit-transform: translateX(0px);\n         -moz-transform: translateX(0px);\n          -ms-transform: translateX(0px);\n           -o-transform: translateX(0px);\n              transform: translateX(0px);\n}\n\n .inner-box .image .overlay-box .overlay-inner{\n    position: absolute;\n    left: 0px;\n    right: 0px;\n    top: 50%;\n    transform: translateY(-50%);\n    z-index:1;\n    padding: 10px 20px;\n    text-align: center;\n}\n\n \n .inner-box .image .overlay-box .overlay-inner .overlay-content{\n    display: block;\n    width: 100%;\n    text-align: center;\n    \n    i{\n      font-size: 28px;\n    }\n}\n\n\n .inner-box .image h3{\n  color:$white;\n}\n\n.overlay-content{\n    h5{\n      text-transform: capitalize;\n      color: #ffffff;\n      padding: 0px;\n      margin-bottom: 0px;\n      font-size: 2rem;\n      text-align: center;\n      -webkit-transform: translateX(0px);\n         -moz-transform: translateX(0px);\n          -ms-transform: translateX(0px);\n           -o-transform: translateX(0px);\n              transform: translateX(0px);\n    -ms-transition: all 0.3s;\n    -moz-transition: all 0.3s;\n    -webkit-transition: all 0.3s;\n    -o-transition: all 0.3s;\n    transition: all 0.3s;\n    }\n\n    p{\n    \tfont-size: 14px;\n      margin-bottom: 0px;\n      padding: 0px 8px;\n      margin-top: 2px;\n      text-transform: capitalize;\n      background: rgba(255,255,255,0.9);\n      color: #2f3238;\n      -webkit-transform: translateX(-150px);\n         -moz-transform: translateX(-150px);\n          -ms-transform: translateX(-150px);\n           -o-transform: translateX(-150px);\n              transform: translateX(-150px);\n    -ms-transition: all 0.5s;\n    -moz-transition: all 0.5s;\n    -webkit-transition: all 0.5s;\n    -o-transition: all 0.5s;\n    transition: all 0.5s;\n    }\n}\n\n\n\n.portfolio-image{\n    width: 60px;\n    height: 60px;\n    display: inline-block;\n    text-align: center;\n    background: $black;\n    color: $white;\n    padding-top: 16px;\n    position: absolute;\n    top: 40%;\n    font-size: 22px;\n    margin-left: -28px;\n    left:50%;\n}\n\n// POrtfolio single\n// \n\n\n.info{\n  a{\n    margin-right: 10px;\n  }\n}",".service-home{\n\tposition: relative;\n}\n\n.service-item{\n\ti{\n\t\tfont-size: 35px;\n\t\tfloat: left;\n\t\twidth: 65px;\n\t\theight: 120px;\n\t}\n\t\n}",".testimonial-content{\n\ttext-align: center;\n\n\timg{\n    \t// box-shadow: 0 20px 30px rgba(0, 0, 0, 0.1);\n\t}\n\tpadding: 25px;\n    position: relative;\n\n\ti{\n\t\tfont-size: 60px;\n\t}\n\n\tp{\n\t\tmargin-top: 30px;\n\t\tmargin-bottom: 25px;\n\t}\n\n}",".about-info{\n\th3{\n\t\tmargin-top: 15px;\n\t}\n\t\n}\n\n.progress-bar-content{\n\tmargin-bottom: 25px;\n\n\t.progress-title{\n\t\ttext-transform: capitalize;\n\t\tfont-size: 14px;\n\t\tcolor: $blac